(() => {
  const { checkAvailability } = window.TeamFitLogic;
  const { validateManagerDecision, createDecisionMessageState, createScheduleConfirmationState } = window.TeamFitDecision;
  const review = window.TeamFitReview.createReviewState();
  const today = new Date().toISOString().slice(0, 10);
  const plusDays = (days) => { const date = new Date(`${today}T00:00:00`); date.setDate(date.getDate() + days); return date.toISOString().slice(0, 10); };
  let team = [
    { id: 1, name: 'Maya Chen', skills: 'Graphic design, Layout', dailyCapacity: 6, committedHours: 18, lastConfirmed: plusDays(-3) },
    { id: 2, name: 'Jordan Lee', skills: 'Copywriting, Editing', dailyCapacity: 7, committedHours: 26, lastConfirmed: plusDays(-5) },
    { id: 3, name: 'Priya Shah', skills: 'Content planning, Research', dailyCapacity: 6, committedHours: 22, lastConfirmed: plusDays(-21) },
    { id: 4, name: 'Owen Martin', skills: 'Proofreading, Quality review', dailyCapacity: 5, committedHours: 12, lastConfirmed: '' },
    { id: 5, name: 'Sofia Alvarez', skills: 'Graphic design, Illustration', dailyCapacity: 6, committedHours: 30, lastConfirmed: plusDays(-2) }
  ];
  let latestResults = [], activeDraft = null, hasCurrentCapacityCheck = false;
  const $ = (selector) => document.querySelector(selector);
  const esc = (value) => String(value).replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]));
  const teamBody = $('#team-body'), results = $('#results'), commitmentConfirmation = $('#confirm-commitments'), decisionMessageState = createDecisionMessageState(), scheduleConfirmationState = createScheduleConfirmationState();
  function setInterpretStatus(message, isError = false) { const status = $('#interpret-status'); status.textContent = message; status.classList.toggle('error-message', isError); }
  const rangeKey = () => `${$('#start-date').value}|${$('#deadline').value}`;
  function updateRangeLabels() { const label = `${$('#start-date').value || 'start date'} to ${$('#deadline').value || 'deadline'}`; $('#selected-range').textContent = label; $('#review-range').textContent = label; }
  function resetScheduleConfirmation() { scheduleConfirmationState.reset(); $('#confirm-schedule').checked = false; }
  function updateScheduleConfirmation() { const confirmation = $('#confirm-schedule'); confirmation.disabled = !hasCurrentCapacityCheck || !$('#candidate').value || $('#hold').checked; if (confirmation.disabled) resetScheduleConfirmation(); }
  function renderDecisionState() { const candidate = $('#candidate'), qualified = latestResults.filter((item) => item.status === 'qualified'); resetScheduleConfirmation(); if (!hasCurrentCapacityCheck) { candidate.disabled = true; candidate.innerHTML = '<option value="">Capacity not assessed — candidate selection unavailable</option>'; updateScheduleConfirmation(); return; } candidate.disabled = !qualified.length; candidate.innerHTML = qualified.length ? `<option value="">Choose a potential candidate</option>${qualified.map((item) => `<option value="${item.id}">${esc(item.name)} - ${item.confirmedCapacity} estimated remaining capacity within selected dates</option>`).join('')}` : '<option value="">No potential candidate meets aggregate criteria</option>'; updateScheduleConfirmation(); }
  function renderDecisionMessage() { const state = decisionMessageState.snapshot(), message = $('#decision-message'); message.textContent = state.message; message.classList.toggle('error-message', state.isError); }
  function setDecisionMessage(message, isError = false) { decisionMessageState.set(message, isError); renderDecisionMessage(); }
  function clearDecisionMessage() { decisionMessageState.clear(); renderDecisionMessage(); }
  function invalidateCapacityAssessment(message = 'Capacity not assessed. Update the request and run a new capacity check before selecting a potential candidate.') { hasCurrentCapacityCheck = false; latestResults = []; resetScheduleConfirmation(); clearDecisionMessage(); results.innerHTML = `<div class="empty-state"><p class="eyebrow">Capacity not assessed</p><h2>Potential-candidate selection is unavailable</h2><p>${esc(message)} You may still record a hold decision.</p></div>`; renderDecisionState(); }
  function requireCommitmentReview() { commitmentConfirmation.checked = false; updateRangeLabels(); invalidateCapacityAssessment('The selected period changed. Review committed work again before checking for confirmed candidates.'); }
  function renderTeam() { teamBody.innerHTML = team.map((member) => `<tr data-id="${member.id}"><td><input aria-label="Name" data-key="name" value="${esc(member.name)}"></td><td><input aria-label="Skills" data-key="skills" value="${esc(member.skills)}"></td><td><input aria-label="Daily capacity" type="number" min="0" data-key="dailyCapacity" value="${member.dailyCapacity}"></td><td><input aria-label="Committed work within selected dates" type="number" min="0" data-key="committedHours" value="${member.committedHours}"></td><td><input aria-label="Last confirmed" type="date" data-key="lastConfirmed" value="${member.lastConfirmed}"></td></tr>`).join(''); }
  teamBody.addEventListener('input', (event) => { const input = event.target, member = team.find((person) => person.id === Number(input.closest('tr').dataset.id)); member[input.dataset.key] = ['dailyCapacity', 'committedHours'].includes(input.dataset.key) ? Number(input.value) : input.value; if (input.dataset.key === 'committedHours') commitmentConfirmation.checked = false; invalidateCapacityAssessment('Team availability inputs changed. Run a new capacity check before selecting a candidate.'); });
  function currentRequest() { return { description: $('#description').value.trim(), requiredSkill: $('#skill').value.trim(), estimatedHours: Number($('#hours').value), confirmedHours: Number($('#confirm-hours').value), startDate: $('#start-date').value, deadline: $('#deadline').value, committedHoursConfirmed: commitmentConfirmation.checked }; }
  function statusCopy(result) { const calc = `Calculation: ${result.dailyCapacity} hrs/day x ${result.workdays} weekdays - ${result.committedTaskHours} committed hrs = ${result.netCapacity} estimated remaining capacity within selected dates.`; if (result.status === 'qualified') return `<strong>Potential candidate.</strong> ${result.confirmedCapacity} estimated remaining capacity within selected dates meets the estimate under this aggregate calculation.<br>${calc}`; if (result.status === 'needs-commitment-review') return `<strong>Committed work needs review.</strong> Estimated remaining capacity cannot be used until commitments are reconfirmed.<br>${calc}`; if (result.status === 'needs-confirmation') return `<strong>Availability information needs review.</strong> The last confirmation is not recent enough for this planning check.<br>${calc}`; if (result.status === 'insufficient-capacity') return `<strong>Estimated aggregate capacity is below the request.</strong> ${result.confirmedCapacity} estimated remaining capacity within selected dates is below the estimate.<br>${calc}`; return `<strong>Skill does not match.</strong><br>${calc}`; }
  function renderResults() { const buckets = { qualified: latestResults.filter((x) => x.status === 'qualified'), insufficient: latestResults.filter((x) => x.status === 'insufficient-capacity'), review: latestResults.filter((x) => x.status === 'needs-commitment-review'), confirmation: latestResults.filter((x) => x.status === 'needs-confirmation'), mismatch: latestResults.filter((x) => x.status === 'skill-mismatch') }; const line = (items) => items.length ? `<ul>${items.map((item) => `<li><span>${esc(item.name)}</span><p>${statusCopy(item)}</p></li>`).join('')}</ul>` : '<p class="empty">None</p>'; results.innerHTML = `<div class="result-intro"><span class="eyebrow">Rule-based capacity check complete</span><h3>${buckets.qualified.length ? 'Potential candidates need manager review' : 'No potential candidate meets aggregate criteria'}</h3><p>Capacity is an aggregate estimate only. It does not check daily schedules, leave, time blocks, or dependencies; it does not establish that a client request can be accepted.</p></div><div class="result-grid"><section><h4>Potential candidates</h4>${line(buckets.qualified)}</section><section><h4>Estimated capacity below request</h4>${line(buckets.insufficient)}</section><section><h4>Needs commitment review</h4>${line(buckets.review)}</section><section><h4>Availability information needs review</h4>${line(buckets.confirmation)}</section><section><h4>Other skill matches needed</h4>${line(buckets.mismatch)}</section></div>`; renderDecisionState(); }
  $('#request-form').addEventListener('submit', (event) => { event.preventDefault(); const request = currentRequest(); if (request.estimatedHours !== request.confirmedHours) return alert('Please enter the same effort estimate in both fields.'); if (!request.requiredSkill || !request.startDate || !request.deadline || !request.estimatedHours) return alert('Please complete all request fields.'); if (request.deadline < request.startDate) return alert('The deadline must be on or after the start date.'); latestResults = checkAvailability(team, request); hasCurrentCapacityCheck = true; renderResults(); });
  $('#review-form').addEventListener('submit', (event) => { event.preventDefault(); const hold = $('#hold').checked, candidate = $('#candidate').selectedOptions[0]?.textContent, decision = validateManagerDecision({ hold, description: $('#description').value, note: $('#decision-note').value, candidateId: $('#candidate').value, hasCurrentCapacityCheck, scheduleConfirmed: scheduleConfirmationState.isConfirmed() }); if (!decision.valid) return setDecisionMessage(decision.message, true); setDecisionMessage(hold ? decision.message : `${decision.message} Potential candidate: ${candidate}.`); });

  function factSection(title, key, items, formatter, field = 'text') { return `<section class="ai-facts"><h4>${title}</h4>${items.length ? items.map((item, index) => { const invalid = item.supported === false; return `<label class="ai-fact ${invalid ? 'unsupported' : ''}"><input type="checkbox" data-kind="${key}" data-index="${index}" ${invalid ? 'disabled' : 'checked'}><span><input class="ai-fact-edit" data-kind="${key}" data-index="${index}" data-field="${field}" value="${esc(item[field])}" ${invalid ? 'disabled' : ''}>${formatter(item)}${item.excerpt ? `<small>Evidence: “${esc(item.excerpt)}”</small>` : ''}${invalid ? '<small>Unsupported: excerpt was not found in the original request.</small>' : ''}</span></label>`; }).join('') : '<p class="empty">None stated</p>'}</section>`; }
  function renderDraft(draft, source) { activeDraft = draft; review.setDraft(source); $('#original-request').textContent = source; $('#approve-ai-draft').checked = false; $('#copy-ai-draft').disabled = true; $('#copy-status').textContent = ''; $('#draft-facts').innerHTML = `${factSection('Deliverables', 'deliverables', draft.deliverables, (x) => '', 'text')}${factSection('Quantities', 'quantities', draft.quantities, (x) => `<small>Linked deliverable: ${esc(x.deliverable)}</small>`, 'quantity')}${factSection('Deadlines', 'deadlines', draft.deadlines, (x) => x.needs_clarification ? '<small>Clarification needed</small>' : '', 'text')}${factSection('Materials', 'materials', draft.materials, (x) => `<small>Status: ${esc(x.status)}</small>`, 'text')}<section class="ai-facts"><h4>Missing information</h4>${draft.missing_information.length ? `<ul>${draft.missing_information.map((x) => `<li>${esc(x.item)}: ${esc(x.question)}</li>`).join('')}</ul>` : '<p class="empty">None identified</p>'}</section><section class="ai-facts"><h4>Clarification questions</h4>${draft.clarification_questions.length ? `<ul>${draft.clarification_questions.map((x) => `<li>${esc(x)}</li>`).join('')}</ul>` : '<p class="empty">None identified</p>'}</section>`; $('#ai-draft').hidden = false; }
  $('#draft-facts').addEventListener('input', (event) => { const input = event.target; if (!input.classList.contains('ai-fact-edit') || !activeDraft) return; activeDraft[input.dataset.kind][Number(input.dataset.index)][input.dataset.field] = input.value; $('#approve-ai-draft').checked = false; $('#copy-ai-draft').disabled = true; $('#copy-status').textContent = 'Draft changed. Review and approve it again before copying.'; });
  $('#interpret-button').addEventListener('click', async () => { const text = $('#client-request').value.trim(), button = $('#interpret-button'); if (text.length < 10) { setInterpretStatus('Enter at least 10 characters of request text.', true); return; } button.disabled = true; setInterpretStatus('Interpreting request...'); $('#ai-draft').hidden = true; try { const response = await fetch('/api/interpret-request', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ requestText: text }) }); const contentType = response.headers.get('content-type') || ''; if (!contentType.includes('application/json')) throw new Error(`The local server returned a non-JSON response (HTTP ${response.status}). Restart TeamFit and try again.`); const data = await response.json(); if (!response.ok) throw new Error(data.error || `Interpretation failed (HTTP ${response.status}).`); renderDraft(data.draft, text); setInterpretStatus(`Draft received from ${data.model}. Review before copying anything.`); } catch (error) { activeDraft = null; setInterpretStatus(error.message || 'Interpretation failed. Nothing was applied.', true); } finally { button.disabled = false; } });
  $('#client-request').addEventListener('input', () => { if (activeDraft && !review.sourceChanged($('#client-request').value.trim())) { activeDraft = null; $('#ai-draft').hidden = true; $('#approve-ai-draft').checked = false; $('#copy-ai-draft').disabled = true; setInterpretStatus('Source text changed. The prior AI draft approval was invalidated.', true); } });
  $('#approve-ai-draft').addEventListener('change', (event) => { const valid = event.target.checked && activeDraft && review.approve($('#client-request').value.trim()); $('#copy-ai-draft').disabled = !valid; if (!valid) event.target.checked = false; });
  $('#copy-ai-draft').addEventListener('click', () => { const result = TeamFitReview.copySelectedFacts({ draft: activeDraft || {}, selectedFacts: [...$('#draft-facts').querySelectorAll('input[type="checkbox"][data-kind]:checked')].map((input) => ({ kind: input.dataset.kind, index: Number(input.dataset.index) })), existingDescription: $('#description').value, allowReplace: $('#replace-description').checked, approved: Boolean(activeDraft && review.isApproved($('#client-request').value.trim())) }); $('#copy-status').textContent = result.message; $('#copy-status').classList.toggle('error-message', !result.changed); if (!result.changed) return; $('#description').value = result.description; invalidateCapacityAssessment('Manual request details changed. Run a new capacity check before selecting a candidate.'); if (result.deadline) { $('#deadline').value = result.deadline; $('#deadline').dispatchEvent(new Event('change')); } });

  $('#decision-note').addEventListener('input', clearDecisionMessage); $('#hold').addEventListener('change', () => { resetScheduleConfirmation(); updateScheduleConfirmation(); clearDecisionMessage(); }); $('#candidate').addEventListener('change', () => { resetScheduleConfirmation(); updateScheduleConfirmation(); clearDecisionMessage(); }); $('#confirm-schedule').addEventListener('change', () => { scheduleConfirmationState.set($('#confirm-schedule').checked); clearDecisionMessage(); });
  [$('#description'), $('#skill'), $('#hours'), $('#confirm-hours')].forEach((field) => field.addEventListener('input', () => invalidateCapacityAssessment('Manual request details changed. Run a new capacity check before selecting a candidate.')));
  $('#start-date').value = plusDays(1); $('#deadline').value = plusDays(10); let confirmedRangeKey = ''; commitmentConfirmation.addEventListener('change', () => { if (commitmentConfirmation.checked) confirmedRangeKey = rangeKey(); invalidateCapacityAssessment('Committed work confirmation changed. Run a new capacity check before selecting a candidate.'); }); [$('#start-date'), $('#deadline')].forEach((field) => field.addEventListener('change', () => { if (rangeKey() !== confirmedRangeKey) requireCommitmentReview(); })); updateRangeLabels(); renderTeam(); renderDecisionState();
})();
